/* 木疙瘩全局脚本 / 文件 → 导入 → 脚本。设置网址后可直接粘贴。 */
/* 一体版由 scripts/build-mugeda.py 注入全部资源，无需设置网址。 */
(function (providedMugeda) {
  "use strict";
  var APP_URL = ""; // 联网版：填写部署后的完整 HTTPS 网页地址。
  var PACKED_HTML = ""; // 由打包器填写，请勿手改。
  var ROOT_ID = "luoyang-lantern-embed";
  var started = false;
  var root, frame;

  function message(copy) {
    var note = document.createElement("p");
    note.textContent = copy;
    note.style.cssText = "margin:auto;padding:32px;max-width:28em;font:16px/2 serif;color:#745637;text-align:center";
    root.appendChild(note);
  }
  function mount() {
    if (started || !document.body) return;
    started = true;
    if (document.getElementById(ROOT_ID)) return;
    root = document.createElement("div");
    root.id = ROOT_ID;
    root.style.cssText = "position:fixed;inset:0;z-index:2147483000;display:flex;background:#f6efe2;overflow:hidden;overscroll-behavior:none;isolation:isolate";
    document.body.appendChild(root);
    frame = document.createElement("iframe");
    frame.id = "luoyang-lantern-frame";
    frame.title = "一灯·千年：洛阳宫灯互动长卷";
    frame.setAttribute("allow", "autoplay; fullscreen");
    frame.setAttribute("allowfullscreen", "");
    frame.style.cssText = "position:absolute;inset:0;width:100%;height:100%;border:0;background:#f6efe2";
    if (APP_URL) {
      try {
        var url = new URL(APP_URL, document.baseURI);
        if (!/^https?:$/.test(url.protocol)) throw new Error("网页地址需要使用 HTTP 或 HTTPS。");
        frame.src = url.href;
        root.appendChild(frame);
      } catch (error) { message(error.message); }
      return;
    }
    if (!PACKED_HTML) {
      message("请在脚本的 APP_URL 中填写已部署的网页地址，或改用包含全部资源的《宫灯一体导入.js》。");
      return;
    }
    if (!window.DecompressionStream) {
      message("此浏览器暂不支持一体脚本解包，请使用新版 Chrome / Safari，或改用联网接入脚本。");
      return;
    }
    message("正在展开宫灯长卷……");
    Promise.resolve().then(function () {
      var binary = atob(PACKED_HTML);
      var bytes = new Uint8Array(binary.length);
      for (var i = 0; i < bytes.length; i++) bytes[i] = binary.charCodeAt(i);
      var stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
      return new Response(stream).text();
    }).then(function (html) {
      var note = root.querySelector("p");
      if (note) note.remove();
      frame.srcdoc = html;
      root.appendChild(frame);
    }).catch(function (error) {
      root.replaceChildren();
      message("长卷未能展开，请重新预览。" + error.message);
    });
  }
  function attach(api) {
    if (!api || typeof api.addEventListener !== "function") return false;
    api.addEventListener("renderready", mount);
    if (api.scene && api.scene.dom) mount();
    return true;
  }
  document.addEventListener("mugedaReady", function () {
    attach(window.Mugeda && window.Mugeda.currentAni);
  });
  if (!attach(providedMugeda || (window.Mugeda && window.Mugeda.currentAni))) {
    // 普通 HTML 宿主也可测试；木疙瘩播放器存在时等待其 ready 事件。
    if (!window.Mugeda) {
      if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", mount);
      else mount();
    }
  }
})(typeof mugeda !== "undefined" ? mugeda : null);
